```python
"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
from collections import deque
import heapq


@dataclass
class Edge:
    src: int
    dst: int
    weight: float


class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def _dijkstra(graph: WeightedGraph, source: int, target: Optional[int] = None,
              k: Optional[int] = None) -> Tuple[Dict[int, float], Dict[int, Optional[int]]]:
    dist: Dict[int, float] = {source: 0.0}
    prev: Dict[int, Optional[int]] = {source: None}
    heap = [(0.0, source)]
    settled: Set[int] = set()

    while heap:
        d, u = heapq.heappop(heap)
        if u in settled:
            continue
        settled.add(u)
        if target is not None and u == target:
            break
        if k is not None and len(settled) > k:
            break
        for v, w in graph.adj.get(u, []):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))
    return dist, prev


def _reconstruct(prev: Dict[int, Optional[int]], target: int) -> List[int]:
    path = []
    cur: Optional[int] = target
    while cur is not None:
        path.append(cur)
        cur = prev.get(cur)
    path.reverse()
    return path


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []
    dist, prev = _dijkstra(graph, source, target=target)
    if target not in dist:
        return None, []
    return dist[target], _reconstruct(prev, target)


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    if source not in graph.nodes:
        return {}
    dist, prev = _dijkstra(graph, source)
    return {n: (d, _reconstruct(prev, n)) for n, d in dist.items()}


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    if source not in graph.nodes or k <= 0:
        return []
    dist: Dict[int, float] = {source: 0.0}
    heap = [(0.0, source)]
    settled: List[Tuple[int, float]] = []
    seen: Set[int] = set()
    while heap and len(settled) < k + 1:
        d, u = heapq.heappop(heap)
        if u in seen:
            continue
        seen.add(u)
        settled.append((u, d))
        for v, w in graph.adj.get(u, []):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    # Need full sorted k-nearest; do full Dijkstra if needed
    full_dist, _ = _dijkstra(graph, source)
    items = [(n, d) for n, d in full_dist.items() if n != source]
    items.sort(key=lambda x: x[1])
    return items[:k]


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False
    if source == target:
        return True
    visited = {source}
    q = deque([source])
    while q:
        u = q.popleft()
        for v, _ in graph.adj.get(u, []):
            if v == target:
                return True
            if v not in visited:
                visited.add(v)
                q.append(v)
    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    undirected: Dict[int, List[int]] = {n: [] for n in graph.adj}
    for e in graph._edges:
        undirected[e.src].append(e.dst)
        undirected[e.dst].append(e.src)

    visited: Set[int] = set()
    components: List[Set[int]] = []
    for node in graph.adj:
        if node in visited:
            continue
        comp: Set[int] = set()
        q = deque([node])
        visited.add(node)
        while q:
            u = q.popleft()
            comp.add(u)
            for v in undirected.get(u, []):
                if v not in visited:
                    visited.add(v)
                    q.append(v)
        components.append(comp)
    return components
